import {
  H1,
  H2,
  Text,
  Stack,
  Row,
  Grid,
  Stat,
  Table,
  Callout,
  CollapsibleSection,
  Divider,
  Code,
} from "cursor/canvas";
import type { TableRowTone } from "cursor/canvas";

type Priority = "Blocking" | "High" = "Medium" extends never ? never : "Blocking" | "High" | "Medium";

type Question = {
  priority: "Blocking" | "High" | "Medium";
  text: string;
  ref: string;
};

const priorityTone: Record<Question["priority"], TableRowTone> = {
  Blocking: "danger",
  High: "warning",
  Medium: "info",
};

const mismatchRows: { cells: [string, string, string, string]; tone: TableRowTone }[] = [
  {
    cells: [
      "SSH brute force — 10.0.0.50",
      "4 failed passwords in 4s, then success",
      "≥ 5 failures / 60s → HIGH",
      "No",
    ],
    tone: "danger",
  },
  {
    cells: [
      "Web login brute force — 10.0.0.50",
      "4× 401 on /login in 4s, then 200",
      "≥ 10 failures / 60s → MEDIUM",
      "No",
    ],
    tone: "danger",
  },
  {
    cells: [
      "Web scanning — 172.16.0.20",
      "5 distinct 404 paths in ~2s",
      "≥ 15 distinct paths / 120s → MEDIUM",
      "No",
    ],
    tone: "danger",
  },
  {
    cells: [
      "SSH invalid-user scan — 203.0.113.5",
      "3 invalid-user attempts in 3s",
      "≥ 5 failures / 60s → HIGH",
      "No",
    ],
    tone: "danger",
  },
  {
    cells: [
      "Directory traversal — 203.0.113.5",
      "1 traversal signature match",
      "any signature match → HIGH",
      "Yes",
    ],
    tone: "success",
  },
  {
    cells: [
      "SQL injection — 10.0.0.88",
      "2 SQLi signature matches",
      "any signature match → HIGH",
      "Yes",
    ],
    tone: "success",
  },
  {
    cells: [
      "Cross-file Incident (any IP)",
      "no IP accumulates ≥2 distinct rule hits given rows above",
      "≥2 distinct rules/sources same IP",
      "Zero incidents produced",
    ],
    tone: "danger",
  },
];

const categories: { title: string; note?: string; questions: Question[] }[] = [
  {
    title: "Critical — plan vs. the provided sample logs",
    note: "These determine whether the sample data in task.md can actually demonstrate the engine's headline features.",
    questions: [
      {
        priority: "Blocking",
        text: "The default thresholds (≥5 SSH failures, ≥10 web-login failures, ≥15 distinct 404s) don't fire on the task.md sample — the sample only reaches 4, 4, and 5 respectively. Should defaults be recalibrated so the sample actually demonstrates detection, or is a separate/larger fixture expected for that?",
        ref: "engine-plan.md §10 defaults table · task.md L61-65, L26-30, L42-47",
      },
      {
        priority: "Blocking",
        text: "Because no ThresholdRule fires and no single IP gets ≥2 distinct rule hits, the Correlator produces zero Incidents on the sample data — yet task.md explicitly requires the tool to 'correlate findings where relevant.' Is that acceptable for v1, or should this be fixed before implementation starts?",
        ref: "engine-plan.md §7 · task.md L20",
      },
      {
        priority: "Blocking",
        text: "The two sudo lines — especially 'COMMAND=/bin/cat /etc/shadow' immediately after the SSH brute-force-then-success on the same IP — read like an intentionally planted privilege-escalation scenario. No rule in the plan (Brute Force / Traversal / SQLi / Scanning) would ever flag it. Is a 'sensitive command' or 'success-after-failed-attempts' rule in scope for this phase?",
        ref: "engine-plan.md §1, §6 · task.md L69",
      },
      {
        priority: "Blocking",
        text: "SyslogAuthParser is specified as 'timestamp host process[pid]: message' — but the sudo lines have no [pid] ('server sudo: johndoe : ...'). Will this regex even match sudo lines, or will they silently become ParseErrors, losing that signal entirely regardless of question 3?",
        ref: "engine-plan.md §5 SyslogAuthParser · task.md L69, L71",
      },
      {
        priority: "Blocking",
        text: "webserver.log timestamps carry a UTC offset ('+0000'); auth.log timestamps carry no offset and no year. Comparing an offset-aware datetime to a naive one raises TypeError in Python. What normalization step makes the two comparable before Correlator can join across files?",
        ref: "engine-plan.md §2.2, §7 · task.md L24 vs L61",
      },
    ],
  },
  {
    title: "Parsing & data model",
    questions: [
      {
        priority: "High",
        text: "Beyond default_year, does SyslogAuthParser also need an injected default_timezone so auth.log timestamps land in the same timezone as the Combined-log timestamps?",
        ref: "engine-plan.md §2.2, §5",
      },
      {
        priority: "Medium",
        text: "Is IPv4-only parsing of source_ip sufficient, or does the 'evolving environment' mentioned in task.md's production context imply IPv6 support is needed now?",
        ref: "engine-plan.md §4 · task.md L77",
      },
      {
        priority: "Medium",
        text: "'size of - → 0' conflates 'zero bytes transferred' with 'size unknown.' Should this be None instead, to avoid biasing any future byte-count analytics?",
        ref: "engine-plan.md §5 CombinedLogParser",
      },
      {
        priority: "Medium",
        text: "A garbage request inside an otherwise valid line is called out as 'itself a signal' — but no rule appears to consume that signal. Should there be a dedicated Finding for malformed-but-parseable request lines, or is the phrase just describing parser leniency with no downstream effect?",
        ref: "engine-plan.md §5 CombinedLogParser",
      },
      {
        priority: "High",
        text: "Is LogEntry.source a free-form label (e.g. file path) or a constrained enum (WEB / AUTH)? This directly affects both rule type-filtering and the '≥2 distinct sources' correlation criterion.",
        ref: "engine-plan.md §4, §7",
      },
    ],
  },
  {
    title: "Detection rules & configuration",
    questions: [
      {
        priority: "High",
        text: "Do the web_login_failure / web_404 named presets hardcode the login path (/login) and the failure status set (401 only, or also 403)? Per the 'parameters are data' philosophy, should the path and status codes be configurable rather than baked into the preset name?",
        ref: "engine-plan.md §6, §6.1",
      },
      {
        priority: "Medium",
        text: "The /admin scanning sequence in the sample returns 403, not 404. Should breadth-scanning detection also count 403s (or a configurable status-code set), or is 404-only intentional?",
        ref: "engine-plan.md §6 web_404 · task.md L32-34",
      },
      {
        priority: "High",
        text: "Is distinct_by resolved via arbitrary getattr(entry, field_name), or via a small named-preset registry like match? The plan's 'no eval, no injection surface' safety boundary is explicit for match but silent on distinct_by.",
        ref: "engine-plan.md §6.1 Safety boundary",
      },
      {
        priority: "High",
        text: "Once a ThresholdRule crosses its threshold for an IP, does it fire once and reset/cool down, or does it keep emitting a duplicate Finding on every subsequent qualifying event during a sustained attack?",
        ref: "engine-plan.md §6 ThresholdRule",
      },
      {
        priority: "Medium",
        text: "Does ThresholdRule.flush() do anything meaningful, or is flush purely a PatternSignatureRule concept (end-of-stream aggregation)?",
        ref: "engine-plan.md §6 Rule ABC",
      },
      {
        priority: "High",
        text: "What are the validation semantics for a bad rule spec at build time — unknown type, invalid regex, unknown match preset, threshold=0, negative window? Raise immediately, or collect structured errors the way parse_file collects ParseError for bad lines?",
        ref: "engine-plan.md §6.1 Registry + factory",
      },
      {
        priority: "Medium",
        text: "For a ThresholdRule Finding, does Finding.count mean the raw event count, or the distinct-value count when distinct_by is set? Worth pinning down since this becomes user-facing output later.",
        ref: "engine-plan.md §4 Finding, §6 ThresholdRule",
      },
      {
        priority: "Medium",
        text: "10.0.0.99's POST /api/users burst (4×200 then 1×429) doesn't match any planned rule — not an auth failure, not a 404, not the login path. Is this a deliberate false-positive check (should stay silent), or a hint that an API-abuse/rate-limit rule shape is missing from scope?",
        ref: "task.md L51-55",
      },
    ],
  },
  {
    title: "Correlation",
    questions: [
      {
        priority: "Medium",
        text: "Incident severity 'escalates above the max child severity' — by a fixed +1 level, some other mapping, or capped at CRITICAL when the max child is already CRITICAL?",
        ref: "engine-plan.md §7",
      },
      {
        priority: "Medium",
        text: "Several sample log lines share the exact same second. What's the deterministic tie-break for sorting/clustering findings with identical first_seen, so output ordering is stable across runs?",
        ref: "engine-plan.md §7 · task.md L42-47",
      },
      {
        priority: "High",
        text: "Greedy clustering by 'gap <= window': if one IP has findings at t=0, t=9min, t=19min (each consecutive gap under 10min but total span over 10min), do all three chain into a single Incident via transitive clustering? A worked example in the tests would remove ambiguity here.",
        ref: "engine-plan.md §7",
      },
    ],
  },
  {
    title: "Engine orchestration & non-functional",
    questions: [
      {
        priority: "Medium",
        text: "Is the injected logger expected to be a stdlib logging.Logger, and does passing None safely no-op, or does the engine need an internal null-logger default?",
        ref: "engine-plan.md §8 Engine",
      },
      {
        priority: "High",
        text: "task.md's production context notes 'high volumes of log data continuously.' Is that a forward-looking note for a future CLI/service wrapper only, or does the current engine need bounded per-IP state (eviction/TTL on ThresholdRule deques and signature-aggregation dicts) to avoid unbounded memory growth in long-running use?",
        ref: "engine-plan.md §1 Goals · task.md L77",
      },
      {
        priority: "Medium",
        text: "PatternSignatureRule findings are only emitted on flush() — i.e., end of stream. Is delayed/batch-only signature reporting acceptable given the 'continuous processing' note, or does this design assumption need to be flagged as a documented limitation for the future streaming wrapper?",
        ref: "engine-plan.md §6, §8",
      },
      {
        priority: "Medium",
        text: "Is the engine expected to run on the Python standard library only, or are small third-party deps (e.g. for robust timezone handling) acceptable?",
        ref: "engine-plan.md (unstated)",
      },
    ],
  },
  {
    title: "Testing strategy",
    questions: [
      {
        priority: "Medium",
        text: "Given the mismatch above, should the boundary tests for threshold/window edges explicitly include the exact counts from task.md's sample logs, so there's a regression test proving the shipped defaults do (or intentionally don't) fire on the provided data?",
        ref: "engine-plan.md §9 Testing strategy",
      },
    ],
  },
];

function QuestionsTable({ questions }: { questions: Question[] }) {
  return (
    <Table
      headers={["Priority", "Question", "Reference"]}
      columnAlign={["left", "left", "left"]}
      rowTone={questions.map((q) => priorityTone[q.priority])}
      rows={questions.map((q) => [
        <Text weight="semibold" size="small">
          {q.priority}
        </Text>,
        <Text>{q.text}</Text>,
        <Text size="small" tone="tertiary">
          {q.ref}
        </Text>,
      ])}
    />
  );
}

export default function EnginePlanReview() {
  const blockingCount = categories
    .flatMap((c) => c.questions)
    .filter((q) => q.priority === "Blocking").length;
  const totalCount = categories.flatMap((c) => c.questions).length;

  return (
    <Stack gap={24} style={{ padding: 24, maxWidth: 980 }}>
      <Stack gap={4}>
        <H1>Engine Plan — Implementation Review</H1>
        <Text tone="secondary">
          Review of <Code>docs/engine-plan.md</Code> against the sample logs in{" "}
          <Code>task.md</Code>, scoped to the engine module only (no CLI/output).
        </Text>
      </Stack>

      <Callout tone="danger" title="Headline finding">
        With the plan's proposed default thresholds, none of the volume/breadth
        detection rules fire on the sample logs in task.md — and as a direct
        result, the Correlator produces zero cross-file Incidents on that data,
        even though correlation is the tool's core requirement.
      </Callout>

      <Grid columns={4} gap={16}>
        <Stat value="0 / 4" label="Threshold rules that fire on the sample" tone="danger" />
        <Stat value="0" label="Incidents produced from the sample" tone="danger" />
        <Stat value={String(blockingCount)} label="Blocking questions" tone="warning" />
        <Stat value={String(totalCount)} label="Total questions raised" tone="info" />
      </Grid>

      <Stack gap={12}>
        <H2>Sample data vs. proposed defaults</H2>
        <Text tone="secondary" size="small">
          Checking every rule the plan ships by default against the exact counts in
          task.md's webserver.log and auth.log.
        </Text>
        <Table
          headers={["Scenario", "What the sample contains", "Proposed default", "Fires?"]}
          rowTone={mismatchRows.map((r) => r.tone)}
          rows={mismatchRows.map((r) => r.cells)}
        />
      </Stack>

      <Divider />

      <Stack gap={8}>
        <H2>Open questions, by category</H2>
        <Text tone="secondary" size="small">
          Everything below is worth resolving before writing code. Grouped from most
          to least architecturally consequential.
        </Text>
      </Stack>

      <Stack gap={4}>
        {categories.map((cat) => (
          <CollapsibleSection
            key={cat.title}
            title={cat.title}
            count={cat.questions.length}
            defaultOpen
          >
            <Stack gap={8} style={{ paddingBottom: 8 }}>
              {cat.note ? (
                <Text tone="secondary" size="small" italic>
                  {cat.note}
                </Text>
              ) : null}
              <QuestionsTable questions={cat.questions} />
            </Stack>
          </CollapsibleSection>
        ))}
      </Stack>
    </Stack>
  );
}
